class TraningThread(QThread):
    finished = pyqtSignal()  # Signal to indicate completion

    def __init__(self, config_data, yaml_file_path):
        super().__init__()
        self.config_data = config_data
        self.yaml_file_path = yaml_file_path

    def run(self):
        # try:
        model = YOLO(self.config_data.model_file_path)
        # model.to("cuda")
        results = model.train(data=self.yaml_file_path, imgsz=self.config_data.image_size,
                              workers=self.config_data.workers, epochs=self.config_data.epochs,
                              batch=self.config_data.batch, save_dir=self.config_data.config_path,
                              patience=self.config_data.patience, project=self.config_data.project)


