    def onButtonTestClick(self, event):
        if not self.lbModelPath.text().strip():
            QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng chọn model file")
            return
        image_path, _ = QFileDialog.getOpenFileName(caption="Open Pre-train Model", filter="*.jpg *.bmp *.png")

        if image_path:
            if self.model is None:
                self.model = YOLO(self.config_data.model_file_path)
            frame_mat = cv2.imread(image_path)
            if self.rdbDetection.isChecked():
                time_start = time.perf_counter()

                results = self.model.predict(frame_mat, imgsz=self.config_data.image_size, verbose=False)
                time_end = (time.perf_counter() - time_start) * 1000.0
                file_name = os.path.basename(image_path)
                print(f"Frame {file_name} : {time_end:.2f} ms")

                for r in results:  # mỗi r tương ứng với 1 ảnh
                    for box in r.boxes:
                        conf = box.conf.item()  # độ tin cậy (float)
                        cls = int(box.cls.item())  # class ID
                        name = r.names[cls]
                        print(f"{name}, Confidence: {conf:.2f}")

                img = results[0].plot()  # This plots the detections on the image
                img_rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
                height, width, channel = img_rgb.shape
                bytes_per_line = 3 * width
                q_image = QPixmap.fromImage(QImage(img_rgb.data, width, height, bytes_per_line, QImage.Format_RGB888))
                self.image_window = ImageWindow(q_image)
                self.image_window.setWindowTitle("Image Window")
                self.image_window.setGeometry(100, 100, 800, 600)
                self.image_window.show()

            if self.rdbClassification.isChecked():
                time_start = time.perf_counter()

                results = self.model.predict(frame_mat, imgsz=224, verbose=False)[0]
                time_end = (time.perf_counter() - time_start) * 1000.0
                probs = results.probs
                # lấy chỉ số và tên class top-1
                top1 = probs.top1
                top1_name = self.model.names[top1]
                top1_score = float(probs.data[top1])
                file_name = os.path.basename(image_path)
                print(f"{file_name} -> {top1_name} ({top1_score:.2f}) {time_end:.2f} ms")
                #

                img_rgb = cv2.cvtColor(frame_mat, cv2.COLOR_BGR2RGB)

                # Vẽ text lên ảnh (góc trên bên trái)
                text = f"{top1_name} ({top1_score * 100:.2f}%)"
                font = cv2.FONT_HERSHEY_SIMPLEX
                cv2.putText(img_rgb, text, (20, 40), font, 1.0, (0, 255, 0), 1, cv2.LINE_AA)

                height, width, channel = img_rgb.shape
                bytes_per_line = 3 * width
                #
                # #cv2.putText(img_rgb,top1_name,(255, 255, 255), 1, cv2.LINE_AA)
                q_image = QPixmap.fromImage(QImage(img_rgb.data, width, height, bytes_per_line, QImage.Format_RGB888))
                self.image_window = ImageWindow(q_image)
                self.image_window.setWindowTitle("Image Window")
                self.image_window.setGeometry(100, 100, 800, 600)
                self.image_window.show()

