    def onButtonStartTrainClick(self, event):
        text = self.btnStartTrain.text()
        if text == "TRAIN":
            if not self.lbImgPath.text().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng chọn thư mục ảnh")
                return
            if not self.lbLabelPath.text().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng chọn thư mục label")
                return
            if not self.lbConfigPath.text().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng chọn thư mục lưu config")
                return
            if not self.lbModelPath.text().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng chọn model file")
                return
            if not self.txtEpochs.toPlainText().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng nhập số epoch")
                return
            if not self.txtBatch.toPlainText().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng nhập số batch")
                return
            if not self.txtPatience.toPlainText().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng nhập số patience")
                return
            if not self.txtProject.toPlainText().strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Vui lòng nhập tên prject")
                return
            self.config_data.config_path = self.lbConfigPath.text()
            self.config_data.label_path = self.lbLabelPath.text()
            self.config_data.model_file_path = self.lbModelPath.text()
            self.config_data.image_path = self.lbImgPath.text()
            self.config_data.epochs = int(self.txtEpochs.toPlainText())
            self.config_data.image_size = int(self.spinImgSz.value())
            self.config_data.workers = int(self.spinWorkers.value())
            self.config_data.batch = int(self.txtBatch.toPlainText())
            self.config_data.patience = int(self.txtPatience.toPlainText())
            self.config_data.project = self.txtProject.toPlainText()

            self.copyImageToFolder()
            yaml_file_path = self.createXamlFile()

            if not yaml_file_path.strip():
                QMessageBox.warning(MainWindow, "Thông báo", "Lỗi tạo file xaml")
                return

            self.save_config_file(self.config_data, config_file_name)
            self.train_thread = TraningThread(self.config_data, yaml_file_path=yaml_file_path)
            self.train_thread.finished.connect(self.on_training_finished)
            self.train_thread.start()
            self.btnStartTrain.setText("STOP")
        else:
            self.btnStartTrain.setText("TRAIN")

    def on_training_finished(self):
        # Thông báo khi huấn luyện hoàn tất
        QMessageBox.information(self, "Thông báo", "Huấn luyện đã hoàn tất!")
        self.btnStartTrain.setEnabled(True)  # Kích hoạt lại nút bấm

    def detect_annotator(self,
                         data: str = 'datasets/images',
                         output_dir: str = 'output',
                         det_model: str = 'datasets/best_X6hs.pt',
                         used_device: dict = 'CPU'
                         ):

        # Load the YOLO model
        det_model = YOLO(det_model)

        # Set the datasets path and output directory
        data_path = Path(data)
        if not output_dir:
            output_dir = data_path.parent / 'output'

        os.makedirs(
            output_dir,
            exist_ok=True
        )

        # Run the model on the datasets
        det_results = det_model(
            data_path,
            stream=True,
            device=used_device
        )

        # Iterate over the detection results
        for result in det_results:
            # Get the class IDs and bounding boxes
            class_ids = result.boxes.cls.int().tolist()
            boxes = result.boxes.xywhn

            # Get the image filename and create the annotation filename
            img_filename = os.path.splitext(os.path.basename(result.path))[0]
            ann_filename = img_filename + '.txt'

            # If there are detections, write them to the annotation file
            if len(class_ids):
                with open(os.path.join(output_dir, ann_filename), 'w') as f:
                    for class_id, box in zip(class_ids, boxes):
                        box = map(str, box.tolist())
                        f.write(f'{class_id} ' + ' '.join(box) + '\n')
        QMessageBox.information(self, "Thông báo", "Auto Label đã hoàn tất!")

    def load_config_file(self, file_path):
        # Read the JSON file and convert it back to a dictionary
        if not os.path.isfile(file_path):
            config_data = Config("", "", "", "", 2000, 640, 1, 16, 100, "")
            self.save_config_file(config_data, config_file_name)
            return
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                config_info_data_read = json.load(file)
            # Create an instance of Person from the dictionary
            config_info_class = Config.from_dict(config_info_data_read)
            return config_info_class
        except:
            return None

    def copyImageToFolder(self):
        # images = [f for f in os.listdir(self.config_data.image_path) if
        #           os.path.isfile(os.path.join(self.config_data.image_path, f))]

        images = self.get_all_images(self.config_data.image_path)
        image_train_path = os.path.join(self.config_data.config_path, "data/train/images")
        image_val_path = os.path.join(self.config_data.config_path, "data/val/images")
        label_train_path = os.path.join(self.config_data.config_path, "data/train/labels")
        label_val_path = os.path.join(self.config_data.config_path, "data/val/labels")
        if not os.path.exists(image_train_path):
            os.makedirs(image_train_path)
        if not os.path.exists(image_val_path):
            os.makedirs(image_val_path)
        if not os.path.exists(label_train_path):
            os.makedirs(label_train_path)
        if not os.path.exists(label_val_path):
            os.makedirs(label_val_path)

        index = 0
        for image in images:

            new_image_folder = image_train_path
            new_label_folder = label_train_path
            if index == 4:
                new_image_folder = image_val_path
                new_label_folder = label_val_path
            old_image_path = os.path.join(self.config_data.image_path, image)
            image_path_base = os.path.basename(image)
            new_image_path = os.path.join(new_image_folder, image_path_base)
            old_label_path = os.path.join(self.config_data.label_path, os.path.splitext(image)[0] + ".txt")
            label_path_base = os.path.basename(os.path.splitext(image)[0] + ".txt")
            new_label_path = os.path.join(new_label_folder, label_path_base)
            if not os.path.isfile(old_label_path):
                continue

            shutil.copy(old_image_path, new_image_path)
            shutil.copy(old_label_path, new_label_path)
            index = index + 1
            if index == 5:
                index = 0

    def get_all_images(self, folder_path):

        filter_extensions = {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff", ".webp"}
        image_files = []

        for root, _, files in os.walk(folder_path):
            for filename in files:
                if any(filename.lower().endswith(ext) for ext in filter_extensions):
                    relative_path = os.path.relpath(os.path.join(root, filename), folder_path)
                    image_files.append(relative_path)
        return image_files

    def save_config_file(self, config_info_class, config_file_path):
        # Convert the Person instance to a dictionary
        config_info_data = config_info_class.to_dict()
        # Write the dictionary to a JSON file
        with open(config_file_path, 'w', encoding="utf-8") as file:
            json.dump(config_info_data, file, ensure_ascii=False, indent=4)

    def show_message(self, title, text, icon_type=QMessageBox.Information, buttons=QMessageBox.Ok):
        msg_box = QMessageBox()
        msg_box.setWindowTitle(title)
        msg_box.setText(text)
        msg_box.setIcon(icon_type)
        msg_box.setStandardButtons(buttons)
        # Execute the message box and get the result
        result = msg_box.exec_()
        return result

