    def createXamlFile(self):
        if self.rdbDetection.isChecked():

            class_file_path = os.path.join(self.config_data.label_path, "classes.txt")
            if not os.path.exists(class_file_path):
                QMessageBox.warning('Thông báo', "File classes.txt không tồn tại\r\n"
                                                  "Copy file classes.txt vào thư mục label")
            f = open(class_file_path, "r")

            with open(class_file_path) as file_in:
                lines = []
                for line in file_in:
                    lines.append(line.replace("\r", "").replace("\n", ""))

            # datasets = f.read()
            for name in lines:
                print(name)
            config_file_path = os.path.join(self.config_data.config_path, "detection_screw.yaml")
            f = open(config_file_path, "w")
            f.write("train: " + self.config_data.config_path + "/train_data/train\n" +
                    "val: " + self.config_data.config_path + "/train_data/val\n" +
                    "nc : " + str(lines.__len__()) + "\n" +
                    "names: " + str(lines))
            return config_file_path
        else:
            return ""


